cat > /tmp/mock-server.cjs << 'EOF'
const http = require('http');

const CONTRACT_ID = '11111111-1111-1111-1111-111111111111';

const CONTRACT = { id: CONTRACT_ID, contractName: 'Vendor Services Agreement — MSA/2026/0147', status: 'Approved' };

const SIGNERS = [
  { id: 's1', contractId: CONTRACT_ID, signerName: 'Priya Nair', signerEmail: 'priya.nair@vendorco.com', signerType: 'Internal', signingOrder: 1, signatureMethod: 'In-built E-signature', reminderFrequencyDays: 3, signerStatus: 'Sent', signaturePadCompleted: false },
  { id: 's2', contractId: CONTRACT_ID, signerName: 'Arjun Kapoor', signerEmail: 'arjun.kapoor@vendorco.com', signerType: 'Internal', signingOrder: 2, signatureMethod: 'In-built E-signature', reminderFrequencyDays: 3, signerStatus: 'Sent', signaturePadCompleted: false },
  { id: 's3', contractId: CONTRACT_ID, signerName: 'Sandra Lopes', signerEmail: 'sandra.lopes@partnerco.com', signerType: 'External', signingOrder: 3, signatureMethod: 'DocuSign', reminderFrequencyDays: 3, signerStatus: 'Sent', signaturePadCompleted: false },
];

const SETTINGS = { reminderFrequencyDays: 3, defaultSignatureProvider: 'In-built E-signature' };

const server = http.createServer((req, res) => {
  res.setHeader('Content-Type', 'application/json');
  res.setHeader('Access-Control-Allow-Origin', '*');
  if (req.method === 'OPTIONS') { res.end(); return; }

  if (req.url === `/api/v1/contracts/${CONTRACT_ID}`) {
    res.end(JSON.stringify(CONTRACT));
  } else if (req.url === `/api/v1/contracts/${CONTRACT_ID}/signers`) {
    res.end(JSON.stringify({ contractId: CONTRACT_ID, signers: SIGNERS, sendForSignatureEnabled: true, signingOrderLocked: false }));
  } else if (req.url === '/api/v1/esignature-settings') {
    res.end(JSON.stringify(SETTINGS));
  } else {
    res.statusCode = 404;
    res.end(JSON.stringify({ error: 'Not found', details: [] }));
  }
});

server.listen(5190, () => console.log('mock server on 5190'));
EOF
node /tmp/mock-server.cjs &
sleep 1
curl -s http://127.0.0.1:5190/api/v1/contracts/11111111-1111-1111-1111-111111111111
